    W(0, 50.5, 104, 3, 7, 'wall'),
    W(0, -50.5, 104, 3, 7, 'wall'),
    W(50.5, 0, 3, 104, 7, 'wall'),
    W(-50.5, 0, 3, 104, 7, 'wall')
  ];
}

