+      closeBuy();
+      hide($('#death-overlay'));
+      showRoundBanner(`ROUND ${data.round}`, data.playerWon ? 'ROUND WON' : 'ROUND LOST', `${data.reason.toUpperCase()} · ${data.score.alpha} — ${data.score.bravo}`);
