+      $('#me-title').innerHTML = won ? 'VICTORY' : 'DEFEAT';
+      $('#me-score').textContent = `${data.score.alpha} — ${data.score.bravo}`;
+      $('#me-copy').textContent = won ? 'ALPHA TAKES THE MATCH' : 'BRAVO TAKES THE MATCH';
+      show($('#match-end'));
+      break;
+    }
+    case 'death':
