:root{
  --bg:#070b10; --panel:#0c131a; --panel2:#101a23; --line:rgba(180,210,225,.14);
  --ink:#eef4f4; --muted:#8ca0a8; --dim:#5d7179;
  --orange:#ff5a36; --orange2:#ff8a5c; --cyan:#48ead8; --cyan2:#8ffff1;
  --gold:#ffc85c; --red:#ff4d67; --green:#65ffc2;
  --display:'Barlow Condensed',Impact,sans-serif; --body:'Inter',system-ui,sans-serif;
  --clip:polygon(0 0,calc(100% - 14px) 0,100% 14px,100% 100%,14px 100%,0 calc(100% - 14px));
}
*{box-sizing:border-box;margin:0;padding:0}
html,body,#app{width:100%;height:100%;overflow:hidden;background:var(--bg);color:var(--ink);font-family:var(--body)}
body{-webkit-tap-highlight-color:transparent;user-select:none}
button,input{font:inherit;color:inherit}
button{cursor:pointer;border:0;background:none}
::selection{background:var(--orange);color:#fff}
.hidden{display:none!important}
.screen{position:fixed;inset:0;display:none;opacity:0;pointer-events:none}
.screen.active{display:flex;opacity:1;pointer-events:auto;animation:screenIn .42s cubic-bezier(.2,.7,.2,1) both}
@keyframes screenIn{from{opacity:0;transform:scale(1.012)}to{opacity:1;transform:scale(1)}}
.boot{position:fixed;inset:0;z-index:200;background:#05080b;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;transition:opacity .5s,visibility .5s}
.boot.done{opacity:0;visibility:hidden}
.boot-mark{font-family:var(--display);font-size:64px;font-weight:800;color:var(--orange);letter-spacing:.05em;text-shadow:0 0 40px rgba(255,90,54,.5)}
.boot-line{width:220px;height:2px;background:rgba(255,255,255,.12);overflow:hidden}
.boot-line span{display:block;height:100%;width:40%;background:var(--orange);animation:bootLoad 1.2s ease-in-out infinite}
@keyframes bootLoad{0%{transform:translateX(-120%)}100%{transform:translateX(320%)}}
.boot-copy{font-family:var(--display);font-size:12px;letter-spacing:.28em;color:var(--dim)}

/* shared chrome */
.topbar{height:76px;padding:0 44px;display:flex;align-items:center;justify-content:space-between;position:relative;z-index:4;flex:0 0 auto}
.brand{display:flex;align-items:center;gap:13px}
.brand-mark{width:42px;height:42px;display:grid;place-items:center;font-family:var(--display);font-weight:800;font-size:20px;background:var(--orange);color:#090b0e;clip-path:polygon(0 0,100% 0,100% 72%,72% 100%,0 100%)}
.brand-text{display:flex;flex-direction:column;line-height:1}
.brand-text strong{font-family:var(--display);font-size:24px;letter-spacing:.04em;font-weight:800}
.brand-text span{font-family:var(--display);font-size:10px;letter-spacing:.22em;color:var(--dim);margin-top:5px}
.top-actions{display:flex;align-items:center;gap:9px}
.icon-btn{width:38px;height:38px;border:1px solid var(--line);background:rgba(10,17,23,.6);display:grid;place-items:center;color:var(--muted);font-size:16px;transition:.2s}
.icon-btn:hover{border-color:var(--orange);color:var(--orange);background:rgba(255,90,54,.08)}
.server-pill{font-family:var(--display);font-size:10px;letter-spacing:.2em;color:var(--muted);border:1px solid var(--line);padding:10px 13px;display:flex;align-items:center;gap:8px;background:rgba(8,13,18,.5)}
.server-pill i{width:6px;height:6px;border-radius:50%;background:var(--cyan);box-shadow:0 0 10px var(--cyan);animation:pulse 2s infinite}
@keyframes pulse{50%{opacity:.35}}
.kicker{font-family:var(--display);font-size:11px;letter-spacing:.24em;color:var(--muted);font-weight:600}
.kicker span{color:var(--orange)}
.btn{position:relative;display:flex;align-items:center;justify-content:space-between;gap:24px;padding:18px 22px;font-family:var(--display);font-size:17px;font-weight:700;letter-spacing:.08em;transition:.22s;clip-path:var(--clip);border:1px solid transparent}
.btn b{font-family:var(--body);font-weight:400;font-size:18px}
.btn-primary{background:var(--orange);color:#0a0d10}
.btn-primary:hover{background:#ff7454;transform:translateY(-2px);box-shadow:0 14px 35px rgba(255,90,54,.22)}
.btn-secondary{background:rgba(12,20,27,.8);border-color:var(--line);color:var(--ink)}
.btn-secondary:hover{border-color:var(--cyan);color:var(--cyan);background:rgba(72,234,216,.07);transform:translateY(-2px)}
.btn.small{padding:13px 18px;font-size:14px;gap:14px}
.text-btn{font-family:var(--display);font-size:13px;letter-spacing:.18em;color:var(--muted);padding:10px 0;transition:.2s}
.text-btn:hover{color:var(--orange)}
---
.loading-teams{display:grid;grid-template-columns:1fr 110px 1fr;gap:20px;align-items:center}
.loading-team{display:flex;gap:8px;justify-content:flex-end}
.loading-team.bravo{justify-content:flex-start}
.loading-op{width:80px;border:1px solid var(--line);background:#0a1117;padding:7px;position:relative}
.loading-op .lo-art{aspect-ratio:.8;overflow:hidden;background:#0a1117}
.loading-op .lo-art svg{width:100%;height:100%}
.loading-op b{display:block;font-family:var(--display);font-size:11px;letter-spacing:.1em;text-align:center;margin-top:5px}
.loading-op.alpha{border-color:rgba(72,234,216,.25)}
.loading-op.bravo{border-color:rgba(255,77,103,.25)}
.loading-vs{display:flex;flex-direction:column;align-items:center;gap:8px}
.loading-vs span{font-family:var(--display);font-size:44px;font-weight:800;color:var(--orange);line-height:1}
.loading-vs b{font-family:var(--display);font-size:8px;letter-spacing:.18em;color:var(--dim);white-space:nowrap}
.loading-bar{height:2px;background:rgba(255,255,255,.1);margin:38px auto 14px;width:360px;max-width:70vw;overflow:hidden}
.loading-bar span{display:block;height:100%;width:35%;background:var(--orange);animation:bootLoad 1s ease-in-out infinite}
.loading-copy{font-family:var(--display);font-size:9px;letter-spacing:.2em;color:var(--dim)}

/* game hud */
.game-screen{display:none;position:fixed;inset:0;background:#05090c}
.game-screen.active{display:block}
#scene{position:absolute;inset:0;width:100%;height:100%;display:block;outline:none}
.hud{position:absolute;inset:0;pointer-events:none;z-index:5;font-family:var(--display);opacity:0;transition:opacity .4s}
.game-screen.live .hud{opacity:1}
.hud-top{position:absolute;top:18px;left:50%;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:7px}
.scoreboard{display:flex;align-items:stretch;background:rgba(7,12,16,.8);border:1px solid rgba(180,210,225,.16);backdrop-filter:blur(8px);clip-path:polygon(0 0,100% 0,100% calc(100% - 9px),calc(100% - 9px) 100%,0 100%)}
.team-score{display:flex;align-items:center;gap:9px;padding:10px 16px;min-width:132px}
.team-score.alpha{justify-content:flex-end;border-right:1px solid var(--line)}
.team-score.bravo{justify-content:flex-start;border-left:1px solid var(--line)}
.team-score b{font-size:31px;line-height:1;font-weight:700}
.team-score.alpha b{color:var(--cyan)}
.team-score.bravo b{color:var(--red)}
.team-tag{font-size:9px;letter-spacing:.18em;color:var(--muted)}
.team-score em{font-family:var(--display);font-style:normal;font-size:8px;letter-spacing:.12em;padding:3px 5px;border:1px solid var(--line);color:var(--dim)}
.match-clock{min-width:120px;text-align:center;padding:7px 12px;background:rgba(0,0,0,.24)}
.clock-label{font-size:8px;letter-spacing:.22em;color:var(--orange)}
.clock-time{font-size:26px;line-height:1;font-weight:700;letter-spacing:.04em}
.round-label{font-size:8px;letter-spacing:.17em;color:var(--dim);margin-top:2px}
.objective-strip{display:flex;align-items:center;gap:9px;background:rgba(7,12,16,.62);border:1px solid var(--line);padding:5px 11px;font-size:9px;letter-spacing:.14em;color:var(--muted)}
.obj-site{width:19px;height:19px;display:grid;place-items:center;background:var(--orange);color:#080b0e;font-weight:700;font-size:11px}
.obj-alive{color:var(--cyan);margin-left:5px}
