  const offs = [[-5.2, 0.4], [-2.6, -0.6], [0, 0.2], [2.6, -0.6], [5.2, 0.4]];
  const o = offs[index % 5];
  return { x: sp.x + o[0], z: sp.z + o[1], yaw: side === 'attack' ? 0 : Math.PI };
}

