Now buy functions. Refactor. Add `buyForAgent` before `buyWeapon`. Modify player buyWeapon/buyArmor to client send and call helper.

Implement:
```
buyForAgent(agent, item, tier) {
 if (!agent || !agent.alive || this.phase!=='buy') return false;
 if (item==='armor') { config...; if agent.armor>=config.armor || money<price return false; agent.armor=config.armor; agent.money-=price; return true; }
 const w=WEAPONS[item]; if(!w) return false;
 const signature = w.signature===agent.agentId;
 const price = signature?Math.floor(w.cost*.9):w.cost;
 if (agent.money<price) return false;
 agent.money-=price; agent.primary=item; agent.weaponId=item; agent.ammo=w.mag; agent.reserve=w.reserve; agent.reloading=0;
 if (agent.isPlayer) { this.viewmodel...; }
 else if (agent.mesh) { this.setAgentGun(agent,item); }
 return true;
}
```
`setAgentGun(agent,id)`: remove old gun, createGunMesh(id,0.72), set pos/rotation, add to mesh, update userData.gun. Import createGunMesh already.
```
setAgentGun(agent,id){
 if(!agent.mesh) return;
 const old=agent.mesh.userData.gun; if(old) agent.mesh.remove(old);
 const gun=createGunMesh(id,0.72); gun.position.set(...); gun.rotation...; agent.mesh.add(gun); agent.mesh.userData.gun=gun;
}
```

Player buyWeapon:
```
if (this.netRole==='client') {
 if (this.phase!=='buy'||!this.player.alive) {...}
 const w=WEAPONS[id]; if(!w) return false;
 const signature=...; const price=...;
 if (this.player.money<price) {...}
 this.netLink.send(host,{kind:'buy',item:id});
 // optimistic local apply:
 this.player.money-=price; this.player.primary=id; this.player.weaponId=id; this.player.ammo=w.mag; this.player.reserve=w.reserve; this.player.reloading=0;
 this.setViewmodel(id); sound.buy(); emit purchase; return true;
}
return this.buyForAgent(this.player,id);
```
But `buyForAgent` emits purchase? For host player, we need emit purchase. Add emit in buyForAgent if agent.isPlayer. For remote, no emit. Similarly armor.

Simplify: `buyWeapon`:
```
if (this.netRole==='client') { ...send + optimistic; return true; }
return this.buyForAgent(this.player, id);
```
`buyForAgent` handles money checks and viewmodel, emits purchase for player.

`buyArmor`:
```
if client { config checks, money, armor; send; return true; }
return this.buyForAgent(this.player,'armor',tier);
```

Let's replace the existing buyWeapon and buyArmor block.

input.newString:
buyForAgent(agent, item, tier = 'light') {
  if (!agent || !agent.alive || this.phase !== 'buy') return false;
  if (item === 'armor') {
    const config = tier === 'heavy' ? { price: 800, armor: 50 } : { price: 400, armor: 25 };
    if (agent.armor >= config.armor || agent.money < config.price) return false;
    agent.money -= config.price;
    agent.armor = config.armor;
    if (agent.isPlayer) {
      sound.buy();
      this.emit('purchase', { armor: config.armor, price: config.price });
    }
    return true;
  }
  const w = WEAPONS[item];
  if (!w) return false;
  const signature = w.signature === agent.agentId;
  const price = signature ? Math.floor(w.cost * 0.9) : w.cost;
  if (agent.money < price) return false;
  agent.money -= price;
  agent.primary = item;
  agent.weaponId = item;
  agent.ammo = w.mag;
  agent.reserve = w.reserve;
  agent.reloading = 0;
  if (agent.isPlayer) {
    this.setViewmodel(item);
    sound.buy();
    this.emit('purchase', { weapon: w, price });
  } else {
    this.setAgentGun(agent, item);
  }
  return true;
}

setViewmodel(id) {
  this.viewmodel?.removeFromParent();
  this.viewmodel = makeViewModel(id);
  this.viewmodel.position.copy(this.viewmodel.userData.basePos);
  this.camera.add(this.viewmodel);
}

setAgentGun(agent, id) {
  if (!agent.mesh) return;
  const old = agent.mesh.userData.gun;
  if (old) agent.mesh.remove(old);
  const gun = createGunMesh(id, 0.72);
  gun.position.set(0.27, 1.18, -0.35);
  gun.rotation.set(-0.05, 0, 0);
  agent.mesh.add(gun);
  agent.mesh.userData.gun = gun;
}

buyWeapon(id) {
  if (this.phase !== 'buy' || !this.player.alive) { sound.error(); this.emit('error', 'Buy window closed'); return false; }
  if (this.netRole === 'client') {
    const w = WEAPONS[id];
    if (!w) return false;
    const price = w.signature === this.player.agentId ? Math.floor(w.cost * 0.9) : w.cost;
    if (this.player.money < price) { sound.error(); this.emit('error', 'Not enough credits'); return false; }
    this.netLink?.send(this.netHostId, { kind: 'buy', item: id });
    this.player.money -= price;
    this.player.primary = id;
    this.player.weaponId = id;
    this.player.ammo = w.mag;
    this.player.reserve = w.reserve;
    this.player.reloading = 0;
    this.setViewmodel(id);
    sound.buy();
    this.emit('purchase', { weapon: w, price });
    return true;
  }
  return this.buyForAgent(this.player, id);
}

buyArmor(tier) {
  if (this.phase !== 'buy' || !this.player.alive) { sound.error(); return false; }
  if (this.netRole === 'client') {
    const config = tier === 'heavy' ? { price: 800, armor: 50 } : { price: 400, armor: 25 };
    if (this.player.armor >= config.armor) { sound.error(); this.emit('error', 'Armor already equipped'); return false; }
    if (this.player.money < config.price) { sound.error(); this.emit('error', 'Not enough credits'); return false; }
    this.player.money -= config.price;
    this.player.armor = config.armor;
    this.netLink?.send(this.netHostId, { kind: 'buy', item: 'armor', tier });
    sound.buy();
    this.emit('purchase', { armor: config.armor, price: config.price });
    return true;
  }
  return this.buyForAgent(this.player, 'armor', tier);
}

